import AppKit

/// The FlowIn feather mark — a clean, crisp glyph for the floating badge.
///
/// Pipeline: the feather was keyed out of the raster app icon (chroma key +
/// bbox-proximity component merge to drop the gradient and bevel), then
/// vectorized with potrace into smooth outlines and filled white. Embedded here
/// as a base64 PDF so `NSImage` renders it as true vector — sharp at any size —
/// with no resource bundling (resolves the same in the debug binary and the
/// release .app).
///
/// Used by `ToolbarPanel`.
@MainActor
enum FeatherLogo {
    /// Shared feather image (white vector on transparent), native box 495×666.
    static let image: NSImage = {
        guard let data = Data(base64Encoded: base64),
              let img = NSImage(data: data) else {
            return NSImage(size: NSSize(width: 1, height: 1))
        }
        return img
    }()

    private static let base64 = ""
}
